INSERT INTO blogs (title, slug, short_description, content, image, category_id, meta_keywords, status) VALUES
('Central Bank of India AGM Recruitment 2026 - Apply for 500 Posts', 'central-bank-india-agm-recruitment-2026', 'Central Bank of India has announced a major recruitment drive for Assistant General Manager positions. Eligible candidates can apply online from 15th January 2026.', '<h2>Central Bank of India AGM Recruitment 2026</h2><p>The <strong>Central Bank of India</strong> has released an official notification for the recruitment of <strong>Assistant General Manager (AGM)</strong> posts for the year 2026. Interested and eligible candidates are invited to apply online through the official recruitment portal.</p><h3>Recruitment Overview</h3><table class="exam-table table-striped"><thead><tr><th>Organization</th><td>Central Bank of India</td></tr><tr><th>Post Name</th><td>Assistant General Manager (AGM)</td></tr><tr><th>Total Vacancies</th><td><strong>500 Posts</strong></td></tr><tr><th>Application Mode</th><td>Online</td></tr><tr><th>Job Location</th><td>Across India</td></tr><tr><th>Official Website</th><td><a href="https://www.centralbankofindia.co.in">centralbankofindia.co.in</a></td></tr></thead></table><h3>Important Dates</h3><table class="exam-table table-striped"><thead><tr><th>Event</th><th>Date</th></tr></thead><tbody><tr><td>Application Start Date</td><td><strong>15th January 2026</strong></td></tr><tr><td>Application End Date</td><td><strong>15th February 2026</strong></td></tr><tr><td>Last Date for Fee Payment</td><td>17th February 2026</td></tr><tr><td>Written Exam Date</td><td>22nd March 2026</td></tr><tr><td>Interview Date</td><td>April 2026 (Tentative)</td></tr><tr><td>Final Result Declaration</td><td>May 2026 (Tentative)</td></tr></tbody></table><h3>Vacancy Details</h3><table class="exam-table table-striped"><thead><tr><th>Post Name</th><th>Vacancies</th><th>Category-wise Breakup</th></tr></thead><tbody><tr><td>AGM (Credit)</td><td>200</td><td>UR: 80 | OBC: 50 | SC: 35 | ST: 20 | EWS: 15</td></tr><tr><td>AGM (Risk)</td><td>150</td><td>UR: 60 | OBC: 40 | SC: 25 | ST: 15 | EWS: 10</td></tr><tr><td>AGM (Operations)</td><td>150</td><td>UR: 60 | OBC: 40 | SC: 25 | ST: 15 | EWS: 10</td></tr><tr><td><strong>Total</strong></td><td><strong>500</strong></td><td><strong>UR: 200 | OBC: 130 | SC: 85 | ST: 50 | EWS: 35</strong></td></tr></tbody></table><h3>Eligibility Criteria</h3><table class="exam-table table-striped"><thead><tr><th>Criteria</th><th>Details</th></tr></thead><tbody><tr><td>Age Limit</td><td>21 to 35 years (as on 01.01.2026)</td></tr><tr><td>Age Relaxation</td><td>SC/ST: 5 yrs | OBC: 3 yrs | PwD: 10 yrs</td></tr><tr><td>Education</td><td>Graduation (any discipline) from recognized university</td></tr><tr><td>Experience</td><td>Minimum 5 years in banking/financial sector</td></tr><tr><td>Nationality</td><td>Indian</td></tr></tbody></table><h3>Application Fee</h3><table class="exam-table table-striped"><thead><tr><th>Category</th><th>Application Fee</th></tr></thead><tbody><tr><td>General / OBC</td><td><strong>Rs. 1000/-</strong></td></tr><tr><td>SC / ST / PwD</td><td><strong>Rs. 250/-</strong></td></tr></tbody></table><p><strong>Payment Mode:</strong> Online (Credit Card / Debit Card / Net Banking / UPI)</p><h3>Selection Process</h3><table class="exam-table table-striped"><thead><tr><th>Stage</th><th>Details</th><th>Marks</th></tr></thead><tbody><tr><td>Stage 1: Online Written Exam</td><td>Objective type (MCQ) - 200 questions</td><td>200</td></tr><tr><td>Stage 2: Interview / GD</td><td>Personal Interview + Group Discussion</td><td>50</td></tr><tr><td>Stage 3: Document Verification</td><td>Original document check</td><td>Qualifying</td></tr><tr><td>Stage 4: Medical Examination</td><td>As per bank norms</td><td>Qualifying</td></tr></tbody></table><h3>Exam Pattern</h3><table class="exam-table table-striped"><thead><tr><th>Section</th><th>No. of Questions</th><th>Marks</th><th>Duration</th></tr></thead><tbody><tr><td>Reasoning Ability</td><td>50</td><td>50</td><td rowspan="4">2 Hours</td></tr><tr><td>Quantitative Aptitude</td><td>50</td><td>50</td></tr><tr><td>English Language</td><td>50</td><td>50</td></tr><tr><td>General Awareness & Banking</td><td>50</td><td>50</td></tr><tr><td><strong>Total</strong></td><td><strong>200</strong></td><td><strong>200</strong></td><td></td></tr></tbody></table><p><em>Note: There is a negative marking of 0.25 marks for each wrong answer.</em></p><h3>How to Apply</h3><ol><li>Visit the official website: <a href="https://www.centralbankofindia.co.in">centralbankofindia.co.in</a></li><li>Click on the "Recruitment" section</li><li>Register with your email ID and mobile number</li><li>Fill in the application form with personal and educational details</li><li>Upload scanned photo (20-50KB) and signature (10-20KB)</li><li>Pay the application fee online</li><li>Submit the form and take a printout for future reference</li></ol><h3>Important Links</h3><table class="exam-table table-striped"><thead><tr><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Apply Online</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Official Notification</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Syllabus</td><td><a href="#">Click Here</a></td></tr><tr><td>Official Website</td><td><a href="https://www.centralbankofindia.co.in">centralbankofindia.co.in</a></td></tr></tbody></table><p><strong>Last Updated:</strong> 20th January 2026</p>', 'recruitment-banner.svg', 3, 'central bank, recruitment, banking jobs, AGM', 'published'),
('Bihar Board 12th Result 2026 Declared - Check Now', 'bihar-board-12th-result-2026-declared', 'Bihar School Examination Board (BSEB) has announced the 12th Intermediate Result 2026. Students can check their results on the official website.', '<h2>Bihar Board 12th Result 2026 - Official Declaration</h2><p>The <strong>Bihar School Examination Board (BSEB)</strong>, Patna has officially declared the <strong>Class 12th Intermediate Annual Examination Result 2026</strong> on its official website. Students who appeared for the examination can now check their results online.</p><h3>Result Summary</h3><table class="exam-table table-striped"><thead><tr><th>Particulars</th><th>Details</th></tr></thead><tbody><tr><td>Board Name</td><td>Bihar School Examination Board (BSEB)</td></tr><tr><td>Exam Name</td><td>Intermediate (Class 12th) Annual Exam 2026</td></tr><tr><td>Total Students Appeared</td><td><strong>13,50,245</strong></td></tr><tr><td>Overall Pass Percentage</td><td><strong>78.2%</strong></td></tr><tr><td>Topper Name</td><td>Priya Kumari</td></tr><tr><td>Topper Marks</td><td><strong>473/500 (94.6%)</strong></td></tr><tr><td>Topper School</td><td>St. Joseph''s Convent, Patna</td></tr><tr><td>Result Date</td><td><strong>18th March 2026</strong></td></tr><tr><td>Official Website</td><td><a href="https://biharboardonline.bihar.gov.in">biharboardonline.bihar.gov.in</a></td></tr></tbody></table><h3>Stream-wise Pass Percentage</h3><table class="exam-table table-striped"><thead><tr><th>Stream</th><th>Pass Percentage</th><th>Students Appeared</th><th>Students Passed</th></tr></thead><tbody><tr><td>Science</td><td>82.5%</td><td>4,50,000</td><td>3,71,250</td></tr><tr><td>Commerce</td><td>76.8%</td><td>5,00,000</td><td>3,84,000</td></tr><tr><td>Arts</td><td>74.1%</td><td>4,00,245</td><td>2,96,582</td></tr><tr><td><strong>Overall</strong></td><td><strong>78.2%</strong></td><td><strong>13,50,245</strong></td><td><strong>10,51,832</strong></td></tr></tbody></table><h3>Top 10 Toppers List</h3><table class="exam-table table-striped"><thead><tr><th>Rank</th><th>Name</th><th>School</th><th>Stream</th><th>Marks</th><th>Percentage</th></tr></thead><tbody><tr><td>1</td><td>Priya Kumari</td><td>St. Joseph''s Convent, Patna</td><td>Science</td><td>473/500</td><td>94.6%</td></tr><tr><td>2</td><td>Aman Kumar Singh</td><td>DAV Public School, Patna</td><td>Science</td><td>468/500</td><td>93.6%</td></tr><tr><td>3</td><td>Neha Kumari</td><td>Bharat Inter College, Muzaffarpur</td><td>Commerce</td><td>465/500</td><td>93.0%</td></tr><tr><td>4</td><td>Rohit Ranjan</td><td>St. Michael''s High School, Patna</td><td>Science</td><td>461/500</td><td>92.2%</td></tr><tr><td>5</td><td>Shruti Sinha</td><td>Patna Women''s College, Patna</td><td>Arts</td><td>458/500</td><td>91.6%</td></tr></tbody></table><h3>How to Check Result</h3><ol><li>Visit the official website: <a href="https://biharboardonline.bihar.gov.in">biharboardonline.bihar.gov.in</a></li><li>Click on the <strong>"Intermediate Result 2026"</strong> link on the homepage</li><li>Enter your <strong>Roll Number</strong> and <strong>Registration Number</strong></li><li>Select your stream (Science / Commerce / Arts)</li><li>Click on <strong>"Submit"</strong> button</li><li>Your result will be displayed on the screen</li><li>Download and take a printout for future reference</li></ol><h3>Result via SMS</h3><p>Students can also check their result via SMS. Send your Roll Number to <strong>56263</strong>.</p><p><strong>Format:</strong> <code>BSEB12 &lt;space&gt; ROLL NUMBER</code></p><h3>Revaluation Process</h3><table class="exam-table table-striped"><thead><tr><th>Event</th><th>Date</th></tr></thead><tbody><tr><td>Revaluation Form Start Date</td><td>20th March 2026</td></tr><tr><td>Revaluation Form End Date</td><td>10th April 2026</td></tr><tr><td>Revaluation Fee</td><td>Rs. 100/- per subject</td></tr><tr><td>Revaluation Result Date</td><td>May 2026 (Tentative)</td></tr></tbody></table><h3>Important Links</h3><table class="exam-table table-striped"><thead><tr><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Check Result Online</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Mark Sheet</td><td><a href="#">Click Here</a></td></tr><tr><td>Apply for Revaluation</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Original Mark Sheet</td><td><a href="#">Click Here</a></td></tr><tr><td>Official Website</td><td><a href="https://biharboardonline.bihar.gov.in">biharboardonline.bihar.gov.in</a></td></tr></tbody></table><p><strong>Last Updated:</strong> 19th March 2026</p>', 'result-banner.svg', 2, 'bihar board, 12th result, BSEB, intermediate result', 'published'),
('UPSC NDA Admit Card 2026 Released - Download Now', 'upsc-nda-admit-card-2026-released', 'Union Public Service Commission has released the NDA Admit Card 2026. Candidates who have applied can download their hall ticket from the official website.', '<h2>UPSC NDA Admit Card 2026 - Official Release</h2><p>The <strong>Union Public Service Commission (UPSC)</strong> has officially released the <strong>National Defence Academy (NDA) &amp; Naval Academy Examination Admit Card 2026</strong>. Candidates who have successfully applied for the examination can now download their hall ticket from the official UPSC website.</p><h3>Exam Details</h3><table class="exam-table table-striped"><thead><tr><th>Particulars</th><th>Details</th></tr></thead><tbody><tr><td>Conducting Body</td><td>Union Public Service Commission (UPSC)</td></tr><tr><td>Exam Name</td><td>NDA &amp; Naval Academy Examination (I) 2026</td></tr><tr><td>Exam Date</td><td><strong>14th April 2026</strong></td></tr><tr><td>Exam Timings</td><td>9:00 AM - 12:00 PM (Mathematics) | 2:00 PM - 5:00 PM (GAT)</td></tr><tr><td>Exam Mode</td><td>Offline (Pen &amp; Paper)</td></tr><tr><td>Total Vacancies</td><td><strong>395 Posts</strong></td></tr><tr><td>Official Website</td><td><a href="https://upsc.gov.in">upsc.gov.in</a></td></tr></tbody></table><h3>Important Dates</h3><table class="exam-table table-striped"><thead><tr><th>Event</th><th>Date</th></tr></thead><tbody><tr><td>Application Start Date</td><td>20th December 2025</td></tr><tr><td>Application End Date</td><td>10th January 2026</td></tr><tr><td>Admit Card Release Date</td><td><strong>28th March 2026</strong></td></tr><tr><td>Exam Date</td><td><strong>14th April 2026</strong></td></tr><tr><td>Result Declaration</td><td>June 2026 (Tentative)</td></tr><tr><td>SSB Interview</td><td>July-August 2026</td></tr></tbody></table><h3>How to Download Admit Card</h3><ol><li>Visit the official UPSC website: <a href="https://upsc.gov.in">upsc.gov.in</a></li><li>Click on the <strong>"Admit Certificate"</strong> link on the homepage</li><li>Select <strong>"NDA &amp; NA Exam (I) 2026"</strong></li><li>Enter your <strong>Registration ID</strong> and <strong>Date of Birth</strong></li><li>Click on <strong>"Submit"</strong> button</li><li>Your admit card will be displayed on the screen</li><li>Download and take a clear printout (preferably in color)</li></ol><h3>Important Instructions for Exam Day</h3><table class="exam-table table-striped"><thead><tr><th>S.No.</th><th>Instruction</th><th>Details</th></tr></thead><tbody><tr><td>1</td><td>Reporting Time</td><td><strong>7:30 AM</strong> (Candidates must reach 90 min before exam)</td></tr><tr><td>2</td><td>ID Proof</td><td>Aadhaar Card / PAN Card / Voter ID / Driving License</td></tr><tr><td>3</td><td>Photographs</td><td>2 Passport size photographs (same as application)</td></tr><tr><td>4</td><td>Admit Card</td><td>Original printout of e-Admit Card (color preferred)</td></tr><tr><td>5</td><td>Stationery</td><td>Black Ball Point Pen only. No calculator/device allowed</td></tr><tr><td>6</td><td>Prohibited Items</td><td>Mobile phone, smartwatch, calculator, any electronic device</td></tr></tbody></table><h3>Exam Centers</h3><p>The exam will be conducted in the following cities across India:</p><p><strong>Delhi | Mumbai | Kolkata | Chennai | Bengaluru | Hyderabad | Allahabad | Lucknow | Jaipur | Chandigarh | Patna | Thiruvananthapuram | Bhubaneswar | Guwahati</strong></p><h3>Exam Pattern</h3><table class="exam-table table-striped"><thead><tr><th>Paper</th><th>Subject</th><th>Duration</th><th>Marks</th><th>Negative Marking</th></tr></thead><tbody><tr><td>Paper I</td><td>Mathematics</td><td>2.5 Hours</td><td>300</td><td>0.83 per wrong answer</td></tr><tr><td>Paper II</td><td>General Ability Test (GAT)</td><td>2.5 Hours</td><td>600</td><td>2.08 per wrong answer</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>5 Hours</strong></td><td><strong>900</strong></td><td></td></tr></tbody></table><h3>SSB Interview Process</h3><table class="exam-table table-striped"><thead><tr><th>Stage</th><th>Duration</th><th>Details</th></tr></thead><tbody><tr><td>Stage I</td><td>1 Day</td><td>Officer Intelligence Rating (OIR) + PP&amp;DT (Picture Perception &amp; Description Test)</td></tr><tr><td>Stage II</td><td>4 Days</td><td>Psychological Test, GTO Tasks, Personal Interview, Conference</td></tr><tr><td>Medical Test</td><td>3-5 Days</td><td>Comprehensive medical examination at nearest military hospital</td></tr></tbody></table><h3>Important Links</h3><table class="exam-table table-striped"><thead><tr><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Download Admit Card</td><td><a href="#">Click Here</a></td></tr><tr><td>Official Notification</td><td><a href="#">Click Here</a></td></tr><tr><td>Exam Syllabus</td><td><a href="#">Click Here</a></td></tr><tr><td>Official Website</td><td><a href="https://upsc.gov.in">upsc.gov.in</a></td></tr></tbody></table><p><strong>Last Updated:</strong> 29th March 2026</p>', 'admit-card-banner.svg', 1, 'UPSC, NDA admit card, defence exam, hall ticket', 'published'),
('New Education Policy 2026: Key Updates for Students', 'new-education-policy-2026-updates', 'The Ministry of Education has announced significant updates to the National Education Policy 2026 affecting curriculum, assessment, and higher education.', '<h2>National Education Policy (NEP) 2026 - Key Updates</h2><p>The <strong>Ministry of Education</strong>, Government of India has announced major updates to the <strong>National Education Policy (NEP) 2026</strong>. These changes will significantly impact the education system across India, from school-level curriculum to higher education reforms.</p><h3>Policy Overview</h3><table class="exam-table table-striped"><thead><tr><th>Particulars</th><th>Details</th></tr></thead><tbody><tr><td>Ministry</td><td>Ministry of Education, Govt. of India</td></tr><tr><td>Policy Name</td><td>National Education Policy (NEP) 2026</td></tr><tr><td>Previous Policy</td><td>National Policy on Education, 1986</td></tr><tr><td>Implementation Start</td><td>Academic Year 2026-27</td></tr><tr><td>Official Website</td><td><a href="https://www.education.gov.in">education.gov.in</a></td></tr></tbody></table><h3>Key Changes at a Glance</h3><h3>1. School Education Reforms (5+3+3+4 Structure)</h3><table class="exam-table table-striped"><thead><tr><th>Stage</th><th>Classes</th><th>Age Group</th><th>Key Features</th></tr></thead><tbody><tr><td>Foundational</td><td>Pre-school to Class 2</td><td>3-8 years</td><td>Play-based learning, multilingual education</td></tr><tr><td>Preparatory</td><td>Class 3 to Class 5</td><td>8-11 years</td><td>Interactive learning, introduction to coding</td></tr><tr><td>Middle</td><td>Class 6 to Class 8</td><td>11-14 years</td><td>Vocational training, experiential learning</td></tr><tr><td>Secondary</td><td>Class 9 to Class 12</td><td>14-18 years</td><td>Flexible subject choices, critical thinking focus</td></tr></tbody></table><h3>2. Higher Education Reforms</h3><ul><li><strong>Multiple Entry &amp; Exit Options</strong> in undergraduate programs:</li></ul><table class="exam-table table-striped"><thead><tr><th>Duration</th><th>Certificate/Degree</th><th>Credits Required</th></tr></thead><tbody><tr><td>1 Year</td><td>Certificate Program</td><td>40 Credits</td></tr><tr><td>2 Years</td><td>Diploma / Advanced Certificate</td><td>80 Credits</td></tr><tr><td>3 Years</td><td>Bachelor''s Degree</td><td>120 Credits</td></tr><tr><td>4 Years</td><td>Bachelor''s Degree (Honours / Research)</td><td>160 Credits</td></tr></tbody></table><ul><li><strong>Academic Bank of Credits (ABC):</strong> Digital storage of academic credits earned by students</li><li><strong>Multiple Entry/Exit:</strong> Students can pause and resume their education</li><li><strong>Research Integration:</strong> 4-year bachelor''s program includes research component</li></ul><h3>3. Assessment Reforms</h3><table class="exam-table table-striped"><thead><tr><th>Aspect</th><th>Old System</th><th>New System (NEP 2026)</th></tr></thead><tbody><tr><td>Exam Frequency</td><td>Annual / Board exams</td><td>360-degree holistic assessment</td></tr><tr><td>Focus</td><td>Rote memorization</td><td>Conceptual understanding &amp; analytical skills</td></tr><tr><td>Board Exams</td><td>Class 10 &amp; 12</td><td>Class 12 only (redesigned for competency)</td></tr><tr><td>Grading</td><td>Percentage-based</td><td>Letter grades with GPA system</td></tr><tr><td>Self-Assessment</td><td>Not included</td><td>Peer review + self-evaluation included</td></tr></tbody></table><h3>4. Language &amp; Curriculum</h3><ul><li><strong>Mother tongue/local language</strong> as medium of instruction up to Class 5</li><li><strong>No rigid separation</strong> between Arts, Science, and Commerce streams</li><li><strong>Coding from Class 6</strong> onwards as part of curriculum</li><li><strong>Vocational education</strong> integration from Class 6 with internships</li></ul><h3>5. Teacher Education Reforms</h3><table class="exam-table table-striped"><thead><tr><th>Current Requirement</th><th>New Requirement (NEP 2026)</th></tr></thead><tbody><tr><td>B.Ed. (2 years)</td><td>Integrated 4-year B.Ed. after Class 12</td></tr><tr><td>CTET/STET mandatory</td><td>National Teacher Eligibility Test (NTET)</td></tr><tr><td>No continuous training</td><td>50 hours of annual CPD (Continuous Professional Development)</td></tr></tbody></table><h3>6. Digital Education Initiatives</h3><ul><li><strong>DIKSHA Platform</strong> expansion with content in all 22 scheduled languages</li><li><strong>SWAYAM Courses</strong> made mandatory for 20% of credits in UG programs</li><li><strong>Digital infrastructure</strong> in all schools by 2028</li><li><strong>Online assessment system</strong> for all competitive exams</li></ul><h3>Implementation Timeline</h3><table class="exam-table table-striped"><thead><tr><th>Year</th><th>Milestone</th></tr></thead><tbody><tr><td>2026-27</td><td>Phase 1: Foundational &amp; Preparatory stage implementation</td></tr><tr><td>2027-28</td><td>Phase 2: Middle school &amp; Academic Bank of Credits rollout</td></tr><tr><td>2028-29</td><td>Phase 3: Secondary stage reforms &amp; Multiple entry/exit in HE</td></tr><tr><td>2029-30</td><td>Phase 4: Full NEP implementation across all stages</td></tr><tr><td>2030</td><td>Complete transformation target achieved</td></tr></tbody></table><h3>Important Links</h3><table class="exam-table table-striped"><thead><tr><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Full NEP 2026 Document</td><td><a href="#">Click Here</a></td></tr><tr><td>Implementation Guidelines</td><td><a href="#">Click Here</a></td></tr><tr><td>Academic Bank of Credits (ABC)</td><td><a href="#">Click Here</a></td></tr><tr><td>DIKSHA Platform</td><td><a href="https://diksha.gov.in">diksha.gov.in</a></td></tr><tr><td>SWAYAM Courses</td><td><a href="https://swayam.gov.in">swayam.gov.in</a></td></tr><tr><td>Official Website - MoE</td><td><a href="https://www.education.gov.in">education.gov.in</a></td></tr></tbody></table><p><strong>Last Updated:</strong> 10th March 2026</p>', 'education-banner.svg', 4, 'education policy, NEP, curriculum, students', 'published'),
('PM Vishwakarma Yojana 2026 - Registration Open', 'pm-vishwakarma-yojana-2026-registration', 'Pradhan Mantri Vishwakarma Yojana 2026 is now open for registration. Traditional artisans and craftspeople can avail financial assistance up to Rs. 3 lakh.', '<h2>PM Vishwakarma Yojana 2026 - Complete Guide</h2><p>The <strong>Pradhan Mantri Vishwakarma Yojana</strong> has been launched by the Government of India to support traditional artisans and craftspeople across the country. This scheme provides comprehensive support including financial assistance, skill training, toolkit incentives, and market linkage to empower traditional artisans.</p><h3>Scheme Overview</h3><table class="exam-table table-striped"><thead><tr><th>Particulars</th><th>Details</th></tr></thead><tbody><tr><td>Scheme Name</td><td>PM Vishwakarma Yojana</td></tr><tr><td>Launched By</td><td>Government of India (Ministry of MSME)</td></tr><tr><td>Launch Date</td><td>14th September 2023</td></tr><tr><td>Phase 2 Registration</td><td><strong>1st January 2026</strong></td></tr><tr><td>Beneficiaries</td><td>Traditional artisans &amp; craftspeople</td></tr><tr><td>Total Budget</td><td>Rs. 13,000 Crore (for 5 years)</td></tr><tr><td>Official Website</td><td><a href="https://pmvishwakarma.gov.in">pmvishwakarma.gov.in</a></td></tr></tbody></table><h3>Benefits of PM Vishwakarma Yojana</h3><table class="exam-table table-striped"><thead><tr><th>Benefit</th><th>Details</th></tr></thead><tbody><tr><td>Financial Assistance</td><td><strong>First Tranche:</strong> Up to Rs. 1 Lakh<br><strong>Second Tranche:</strong> Up to Rs. 2 Lakh<br><strong>Total:</strong> Up to Rs. 3 Lakh</td></tr><tr><td>Interest Rate</td><td><strong>5% per annum</strong> (Concessional rate)</td></tr><tr><td>Toolkit Incentive</td><td><strong>Rs. 15,000</strong> (modern toolkit set provided)</td></tr><tr><td>Skill Training</td><td><strong>5-7 days</strong> basic training (free)<br><strong>15 days</strong> advanced training with stipend</td></tr><tr><td>Training Stipend</td><td><strong>Rs. 500 per day</strong> during advanced training</td></tr><tr><td>Brand Promotion</td><td>Support for branding, marketing &amp; quality certification</td></tr><tr><td>Digital Presence</td><td>Onboarding on e-commerce platforms (GeM, ONDC)</td></tr></tbody></table><h3>Eligibility Criteria</h3><table class="exam-table table-striped"><thead><tr><th>Criteria</th><th>Details</th></tr></thead><tbody><tr><td>Age Limit</td><td>Minimum 18 years (No upper age limit)</td></tr><tr><td>Community</td><td>Must belong to Vishwakarma community (traditional artisan)</td></tr><tr><td>Occupation</td><td>Must be engaged in one of the <strong>18 covered trades</strong></td></tr><tr><td>Identity</td><td>Valid Aadhaar Card mandatory</td></tr><tr><td>Income</td><td>No income limit</td></tr><tr><td>Previous Benefit</td><td>Should not have availed similar govt. loan scheme</td></tr></tbody></table><h3>18 Covered Trades</h3><table class="exam-table table-striped"><thead><tr><th>S.No.</th><th>Trade Name</th><th>S.No.</th><th>Trade Name</th></tr></thead><tbody><tr><td>1</td><td>Carpenter (Suthar)</td><td>10</td><td>Sculptor (Moorkarti)</td></tr><tr><td>2</td><td>Blacksmith (Lohar)</td><td>11</td><td>Basket/Moonj/Bamboo Worker</td></tr><tr><td>3</td><td>Goldsmith (Sonar)</td><td>12</td><td>Dhobi (Washerman)</td></tr><tr><td>4</td><td>Potter (Kumhar)</td><td>13</td><td>Barber (Naai)</td></tr><tr><td>5</td><td>Mason (Raj mistr)</td><td>14</td><td>Garland Maker (Malakar)</td></tr><tr><td>6</td><td>Cobbler (Mochi)</td><td>15</td><td>Stone Breaker</td></tr><tr><td>7</td><td>Tailor (Darji)</td><td>16</td><td>Hammer &amp; Tool Maker</td></tr><tr><td>8</td><td>Painter (Chitrakar)</td><td>17</td><td>Doll &amp; Toy Maker</td></tr><tr><td>9</td><td>Fisherman (Kewat)</td><td>18</td><td>Washing Machine Repair</td></tr></tbody></table><h3>How to Apply</h3><ol><li>Visit the official website: <a href="https://pmvishwakarma.gov.in">pmvishwakarma.gov.in</a></li><li>Click on <strong>"New Registration"</strong></li><li>Enter your <strong>Aadhaar Number</strong> for verification</li><li>Fill in personal details (name, address, mobile number)</li><li>Select your <strong>trade/occupation</strong> from the list of 18 trades</li><li>Upload required documents (Aadhaar, photo, bank passbook)</li><li>Submit the application form</li><li>Receive registration confirmation via SMS</li><li>Visit your nearest <strong>CSC (Common Service Center)</strong> for verification</li><li>After verification, you will receive your <strong>PM Vishwakarma Certificate</strong> and <strong>ID Card</strong></li></ol><h3>Documents Required</h3><table class="exam-table table-striped"><thead><tr><th>Document</th><th>Details</th></tr></thead><tbody><tr><td>Aadhaar Card</td><td>Mandatory (linked with mobile number)</td></tr><tr><td>Passport Size Photograph</td><td>Recent color photograph</td></tr><tr><td>Bank Passbook / Account</td><td>Active bank account for loan disbursement</td></tr><tr><td>Trade Proof</td><td>Any document showing your artisan work</td></tr><tr><td>Mobile Number</td><td>Active mobile number (linked with Aadhaar)</td></tr></tbody></table><h3>Loan Disbursement Process</h3><table class="exam-table table-striped"><thead><tr><th>Stage</th><th>Details</th><th>Timeline</th></tr></thead><tbody><tr><td>Stage 1: Application</td><td>Submit online application with documents</td><td>1-2 days</td></tr><tr><td>Stage 2: Verification</td><td>CSC / local authority verification</td><td>7-10 days</td></tr><tr><td>Stage 3: Training</td><td>Basic skill training (5-7 days)</td><td>7 days</td></tr><tr><td>Stage 4: Toolkit</td><td>Toolkit incentive disbursement</td><td>15 days after training</td></tr><tr><td>Stage 5: Loan Approval</td><td>First tranche loan (Rs. 1 Lakh)</td><td>30 days after registration</td></tr><tr><td>Stage 6: Second Tranche</td><td>Second tranche loan (Rs. 2 Lakh)</td><td>After 18 months of repayment</td></tr></tbody></table><h3>Important Links</h3><table class="exam-table table-striped"><thead><tr><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Register Online</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Notification</td><td><a href="#">Click Here</a></td></tr><tr><td>Check Application Status</td><td><a href="#">Click Here</a></td></tr><tr><td>List of Beneficiaries</td><td><a href="#">Click Here</a></td></tr><tr><td>Official Website</td><td><a href="https://pmvishwakarma.gov.in">pmvishwakarma.gov.in</a></td></tr></tbody></table><p><strong>Helpline:</strong> 1800-XXX-XXXX (Toll Free) | <strong>Email:</strong> helpdesk@pmvishwakarma.gov.in</p><p><strong>Last Updated:</strong> 5th January 2026</p>', 'sarkari-yojana-banner.svg', 5, 'PM Vishwakarma, sarkari yojana, artisan scheme, government scheme', 'published'),
('SSC CGL 2026 Notification Out - 12000+ Vacancies', 'ssc-cgl-2026-notification-vacancies', 'Staff Selection Commission has released the CGL 2026 notification with over 12,000 vacancies for various Group B and Group C posts in government departments.', '<h2>SSC CGL 2026 - Combined Graduate Level Examination</h2><p>The <strong>Staff Selection Commission (SSC)</strong> has officially released the <strong>Combined Graduate Level (CGL) Examination 2026</strong> notification. This is one of the most popular government recruitment exams offering <strong>12,465 vacancies</strong> across various Group B and Group C posts in different government ministries and departments.</p><h3>Recruitment Overview</h3><table class="exam-table table-striped"><thead><tr><th>Particulars</th><th>Details</th></tr></thead><tbody><tr><td>Conducting Body</td><td>Staff Selection Commission (SSC)</td></tr><tr><td>Exam Name</td><td>Combined Graduate Level (CGL) Examination 2026</td></tr><tr><td>Notification No.</td><td><strong>3/2026-CGL</strong></td></tr><tr><td>Total Vacancies</td><td><strong>12,465 Posts</strong></td></tr><tr><td>Application Start Date</td><td><strong>20th January 2026</strong></td></tr><tr><td>Application End Date</td><td><strong>18th February 2026</strong></td></tr><tr><td>Exam Date</td><td>April-May 2026 (Tentative)</td></tr><tr><td>Official Website</td><td><a href="https://ssc.nic.in">ssc.nic.in</a></td></tr></tbody></table><h3>Important Dates</h3><table class="exam-table table-striped"><thead><tr><th>Event</th><th>Date</th></tr></thead><tbody><tr><td>Notification Release Date</td><td><strong>15th January 2026</strong></td></tr><tr><td>Application Start Date</td><td><strong>20th January 2026</strong></td></tr><tr><td>Last Date to Apply Online</td><td><strong>18th February 2026 (6:00 PM)</strong></td></tr><tr><td>Last Date for Fee Payment</td><td><strong>20th February 2026 (11:59 PM)</strong></td></tr><tr><td>Tier-I Exam Date</td><td>April 2026 (Tentative)</td></tr><tr><td>Tier-II Exam Date</td><td>June 2026 (Tentative)</td></tr><tr><td>Tier-III (Skill Test)</td><td>July 2026 (Tentative)</td></tr><tr><td>Final Result</td><td>September 2026 (Tentative)</td></tr></tbody></table><h3>Vacancy Details</h3><table class="exam-table table-striped"><thead><tr><th>Post Name</th><th>Vacancies</th><th>Department</th></tr></thead><tbody><tr><td>Inspector (Income Tax)</td><td>2,500</td><td>CBIC</td></tr><tr><td>Inspector (Central Excise)</td><td>1,800</td><td>CBIC</td></tr><tr><td>Assistant Section Officer</td><td>2,200</td><td>Central Secretariat</td></tr><tr><td>Inspector (Preventive Officer)</td><td>1,200</td><td>CBIC</td></tr><tr><td>Inspector (Examiner)</td><td>800</td><td>CBIC</td></tr><tr><td>Auditor</td><td>1,500</td><td>CAG / CGDA</td></tr><tr><td>Accountant / JAA</td><td>1,000</td><td>Various Departments</td></tr><tr><td>Tax Assistant</td><td>800</td><td>CBIC</td></tr><tr><td>Upper Division Clerk (UDC)</td><td>465</td><td>Various Ministries</td></tr><tr><td>Other Posts</td><td>200</td><td>Various Departments</td></tr><tr><td><strong>Total</strong></td><td><strong>12,465</strong></td><td></td></tr></tbody></table><h3>Eligibility Criteria</h3><table class="exam-table table-striped"><thead><tr><th>Criteria</th><th>Details</th></tr></thead><tbody><tr><td>Age Limit</td><td>18 to 32 years (varies by post)</td></tr><tr><td>Age Relaxation</td><td>SC/ST: 5 yrs | OBC: 3 yrs | PwD: 10 yrs</td></tr><tr><td>Education</td><td>Bachelor''s degree in any discipline from recognized university</td></tr><tr><td>Nationality</td><td>Indian</td></tr></tbody></table><h3>Application Fee</h3><table class="exam-table table-striped"><thead><tr><th>Category</th><th>Application Fee</th></tr></thead><tbody><tr><td>General / OBC</td><td><strong>Rs. 100/-</strong></td></tr><tr><td>SC / ST / PwD / Ex-Servicemen</td><td><strong>NIL (Exempted)</strong></td></tr></tbody></table><p><strong>Payment Mode:</strong> Online (SBI Challan / Credit Card / Debit Card / Net Banking / UPI)</p><h3>Exam Pattern</h3><h3>Tier-I (Computer Based Examination)</h3><table class="exam-table table-striped"><thead><tr><th>Section</th><th>No. of Questions</th><th>Marks</th><th>Duration</th></tr></thead><tbody><tr><td>General Intelligence &amp; Reasoning</td><td>25</td><td>50</td><td rowspan="4">60 Minutes</td></tr><tr><td>General Awareness</td><td>25</td><td>50</td></tr><tr><td>Quantitative Aptitude</td><td>25</td><td>50</td></tr><tr><td>English Comprehension</td><td>25</td><td>50</td></tr><tr><td><strong>Total</strong></td><td><strong>100</strong></td><td><strong>200</strong></td><td></td></tr></tbody></table><p><em>Note: Negative marking of 0.50 marks for each wrong answer.</em></p><h3>Tier-II (Computer Based Examination)</h3><table class="exam-table table-striped"><thead><tr><th>Module</th><th>No. of Questions</th><th>Marks</th><th>Duration</th></tr></thead><tbody><tr><td>Maths (Section-I)</td><td>30</td><td>90</td><td rowspan="2">2 Hours 15 Min</td></tr><tr><td>Reasoning &amp; GK (Section-II)</td><td>60</td><td>180</td></tr><tr><td>English (Session-I)</td><td>45</td><td>135</td><td rowspan="2">2 Hours 15 Min</td></tr><tr><td>General Awareness (Session-II)</td><td>30</td><td>90</td></tr></tbody></table><h3>Tier-III (Skill Test / Document Verification)</h3><table class="exam-table table-striped"><thead><tr><th>Post</th><th>Skill Test Type</th><th>Qualifying Criteria</th></tr></thead><tbody><tr><td>Assistant Section Officer</td><td>Computer Proficiency Test (CPT)</td><td>Qualifying nature</td></tr><tr><td>Tax Assistant</td><td>DEST (Data Entry Speed Test)</td><td>2000 Key Depressions in 15 Min</td></tr><tr><td>Upper Division Clerk</td><td>DEST</td><td>2000 Key Depressions in 15 Min</td></tr><tr><td>Other Posts</td><td>Document Verification</td><td>Qualifying nature</td></tr></tbody></table><h3>How to Apply</h3><ol><li>Visit the official SSC website: <a href="https://ssc.nic.in">ssc.nic.in</a></li><li>Click on <strong>"Apply"</strong> link for CGL 2026</li><li>Register with your email ID and mobile number</li><li>Fill in the application form (Part-I: Personal details, Part-II: Educational details)</li><li>Upload scanned photograph (20-50KB, 200x230px) and signature (10-20KB, 140x60px)</li><li>Pay the application fee</li><li>Submit the form and download the confirmation page</li><li>Take a printout for future reference</li></ol><h3>Important Links</h3><table class="exam-table table-striped"><thead><tr><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Apply Online</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Official Notification</td><td><a href="#">Click Here</a></td></tr><tr><td>Download Syllabus</td><td><a href="#">Click Here</a></td></tr><tr><td>Previous Year Papers</td><td><a href="#">Click Here</a></td></tr><tr><td>Official Website</td><td><a href="https://ssc.nic.in">ssc.nic.in</a></td></tr></tbody></table><p><strong>Last Updated:</strong> 16th January 2026</p>', 'recruitment-banner.svg', 3, 'SSC CGL, government jobs, recruitment, competitive exam', 'published');
